<template>
 <section class="data-catalog" aria-label="项目数据管理">
  <header class="data-heading"><div><h2>数据管理</h2><p>统一管理项目资料与运行数据 · 仅系统管理员可操作</p></div><el-button :loading="busy" @click="load">刷新数据</el-button></header>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/>
  <template v-if="data">
   <nav class="data-categories" aria-label="数据分类"><button v-for="c in categories" :key="c.id" :class="{active:selected===c.id}" :disabled="busy" @click="select(c.id)"><span>{{c.title}}</span><strong>{{c.id==='ai_logs'?c.items[0]?.fileCount:c.count}} <small>{{c.id==='ai_logs'?'条':'项'}}</small></strong><small>{{fileSize(c.bytes)}}</small></button><button :class="{active:selected==='database'}" :disabled="busy" @click="select('database')"><span>业务数据库</span><strong>{{fileSize(data.database.bytes)}}</strong><small>台账与业务记录 · 受保护</small></button></nav>
   <section v-if="selected==='database'" class="data-detail"><h3>业务数据库</h3><p>{{data.storageNote}}</p><p>库存、出入库、审批等通过对应业务流程维护，不提供整库清空。</p><details><summary>查看数据表占用（估算）</summary><ul class="database-list"><li v-for="table in data.database.tables" :key="table.name"><span>{{table.name}}</span><span>约 {{table.rowCount}} 行 · {{fileSize(table.bytes)}}</span></li></ul></details></section>
   <section v-else-if="category" class="data-detail">
    <header><div><h3>{{category.title}}</h3><p>{{category.description}}</p></div><el-button v-if="['ai_logs','robot_archives'].includes(selected)" type="danger" plain :disabled="busy" @click="cleanup">{{selected==='ai_logs'?'清理90天前记录':'彻底清理删除归档'}}</el-button></header>
    <table v-if="category.items.length"><thead><tr><th>资料名称</th><th>占用 / 状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in visibleItems" :key="item.id"><td><strong>{{item.title}}</strong><small v-if="item.updatedAt">{{time(item.updatedAt)}}</small></td><td>{{fileSize(item.bytes)}}<small v-if="selected==='robot'">{{item.annotationCount}} 处注释</small><small v-if="selected==='knowledge'">{{item.historyCount}} 个历史版本</small><small v-if="selected==='models'">{{item.builtIn?'内置模型':`关联 ${item.referenceCount} 种备件`}}</small><small v-if="selected==='ai_logs'">{{item.fileCount}} 条记录；{{item.eligibleCount}} 条早于保留范围（未完成记录不清理）</small></td><td class="data-actions"><template v-if="selected==='robot'"><el-button link :disabled="busy" @click="remove(item,'analysis')">清除分析</el-button><el-button link type="danger" :disabled="busy" @click="remove(item,'robot')">删除备份</el-button></template><el-button v-else-if="['knowledge','models','images'].includes(selected)" link type="danger" :disabled="busy||!!item.builtIn" @click="remove(item,selected)">{{selected==='images'?'清除图片':'删除资料'}}</el-button><span v-else>{{selected==='robot_archives'?'等待归档清理':'近90天自动保留'}}</span></td></tr></tbody></table><p v-else class="data-empty">暂无数据</p>
    <el-pagination v-if="category.items.length>20" v-model:current-page="page" :page-size="20" :total="category.items.length" layout="prev,pager,next"/>
   </section>
   <p class="data-preserved">保留：{{data.protected.join('；')}}。</p>
   <details @toggle="loadAudit"><summary>运行数据清理记录</summary><p v-if="!audit.length">暂无记录</p><ul><li v-for="row in audit" :key="row.id">{{time(row.createdAt)}} · {{row.kind==='ai_logs'?'调用记录':'机器人归档'}} · {{row.itemCount}} 个文件 · {{fileSize(row.releasedBytes)}} · {{row.status==='complete'?'已完成':row.status==='partial'?'部分完成，请刷新核对':'处理中'}} · 操作人 #{{row.actorId}}</li></ul></details>
  </template>
 </section>
</template>
<script setup>
import {ref,computed,onMounted} from 'vue'
import {ElMessageBox} from 'element-plus'
import {office} from '../api/attendance'
import {fileSize} from '../utils/attendance-display.mjs'
const props=defineProps({legacySummary:{type:Array,default:()=>[]}}),emit=defineEmits(['category','refresh'])
const data=ref(null),busy=ref(false),error=ref(''),message=ref(''),selected=ref('robot'),page=ref(1),audit=ref([])
const categories=computed(()=>[...(data.value?.categories||[]),...['attendance','raw_duty_photo'].map(id=>{const row=props.legacySummary.find(r=>r.kind===id);return {id,title:id==='attendance'?'考勤当前导入':'履职照片',count:row?.itemCount||0,bytes:row?.bytes||0}})])
function select(id){selected.value=id;page.value=1;emit('category',id)}
const category=computed(()=>data.value?.categories.find(c=>c.id===selected.value)),visibleItems=computed(()=>category.value?.items.slice((page.value-1)*20,page.value*20)||[])
const time=v=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})
async function read(){data.value=(await office.get('/data-management')).data}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{await read();emit('refresh')}catch(e){error.value=e.response?.data?.msg||'数据读取失败'}finally{busy.value=false}}
async function remove(item,kind){if(busy.value)return;const effects={analysis:'清除中文注释、总览、分批结果和对话，保留原始ZIP。正在分析时不能清除。',robot:'备份及分析将从所有使用者列表移除，原文件与分析进入删除归档；需要释放空间可随后彻底清理归档。',knowledge:'删除知识条目、历史版本及所有附件，将不再被知识问答检索。',models:'删除模型及其上传文件，解除已绑定的备件关系，保留备件及库存。',images:'删除备件图片，保留备件及库存。'};try{await ElMessageBox.confirm(`“${item.title}”：${effects[kind]}`,'确认数据操作',{type:'warning',confirmButtonText:kind==='robot'?'删除并归档':'确认清除',cancelButtonText:'取消'})}catch{return}busy.value=true;error.value='';message.value='';try{const url={analysis:`/data-management/robot/${item.id}/analysis`,robot:`/robot-program/library/${item.id}`,knowledge:`/knowledge/${item.id}`,models:`/part-models/${item.id}`,images:`/parts/${item.id}/image`}[kind];const result=await office.delete(url,{data:{revision:item.revision}});message.value=result.msg||'操作已完成';await read();page.value=1}catch(e){error.value=e.response?.data?.msg||'操作失败，请刷新重试'}finally{busy.value=false}}
async function cleanup(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{const p=(await office.post('/data-management/cleanup-preview',{kind:selected.value})).data;if(!p.itemCount){message.value='当前没有符合条件的可清理文件';return}try{await ElMessageBox.confirm(`将彻底清理 ${p.itemCount} 个文件，共 ${fileSize(p.totalBytes)}。${p.kind==='ai_logs'?'保留近90天及未完成记录；旧日期的调用用量汇总也会减少。':'已删除备份的原ZIP与分析记录将永久删除；删除标记保留，防止旧浏览器缓存恢复。'}清理不可恢复。`,'核对清理范围',{type:'warning',confirmButtonText:'确认清理',cancelButtonText:'取消'})}catch{return}const result=(await office.post('/data-management/cleanup',{previewId:p.id})).data;message.value=`清理完成，释放 ${fileSize(result.releasedBytes)}`;await read();await loadAudit()}catch(e){error.value=e.response?.data?.msg||'清理失败，请刷新核对'}finally{busy.value=false}}
async function loadAudit(event){if(event&&!event.target.open)return;try{audit.value=(await office.get('/data-management/audit')).data}catch{error.value='清理记录读取失败'}}
onMounted(load)
</script>
<style scoped>
.data-catalog{display:grid;gap:18px;color:#243b50;margin-bottom:28px;min-width:0}.data-heading,.data-detail>header{display:flex;align-items:center;justify-content:space-between;gap:20px}.data-catalog h2{font-size:24px;margin:0}.data-catalog h3{font-size:17px;margin:0 0 9px}.data-catalog p{font-size:13px;color:#748798;line-height:1.8;margin:6px 0}.data-categories{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.data-categories button{display:grid;gap:10px;text-align:left;border:1px solid #dfe7ee;background:white;border-radius:12px;padding:18px;color:inherit;cursor:pointer;font:inherit}.data-categories button.active{border-color:#16898c;background:#eff9f7;box-shadow:inset 0 0 0 1px #16898c}.data-categories button>span{font-size:13px}.data-categories strong{font-size:21px}.data-categories small{font-size:11px;font-weight:400;color:#748798}.data-detail{background:white;border:1px solid #dfe7ee;border-radius:12px;padding:22px;min-width:0}.data-detail table{width:100%;border-collapse:collapse;margin-top:18px;font-size:13px;table-layout:fixed}.data-detail th{text-align:left;background:#f7f9fb;color:#788a9c;padding:12px}.data-detail th:first-child{width:45%}.data-detail td{border-bottom:1px solid #edf1f5;padding:16px 12px;overflow-wrap:anywhere}.data-detail td>small{display:block;color:#7c8e9f;margin-top:6px;line-height:1.7}.data-detail td>strong{font-weight:550}.data-actions{white-space:normal}.data-actions :deep(.el-button){margin:0 12px 0 0}.data-catalog details{font-size:13px;color:#748798;line-height:2}.data-catalog summary{cursor:pointer}.database-list{list-style:none;padding:0}.database-list li{display:flex;justify-content:space-between;gap:16px;overflow-wrap:anywhere}.data-empty{padding:25px;text-align:center}.data-preserved{padding:12px 16px;background:#eaf1f5;border-radius:8px}.data-catalog button:focus-visible{outline:2px solid #087f83;outline-offset:3px}@media(max-width:800px){.data-categories{grid-template-columns:repeat(2,minmax(0,1fr))}.data-detail{padding:14px}.data-heading,.data-detail>header{align-items:flex-start;flex-wrap:wrap}.data-detail th{display:none}.data-detail tr,.data-detail td{display:block}.data-detail td{border:0;padding:7px 0}.data-detail tr{border-bottom:1px solid #edf1f5;padding:10px 0}.data-detail .el-button{min-height:40px}.data-categories button{padding:14px}.database-list li{flex-wrap:wrap}}
</style>
